+function authenticate(store, headers) {
+  const authorization = Object.entries(headers).find(([name]) => name.toLowerCase() === "authorization")?.[1];
+  const token = typeof authorization === "string" && /^Bearer +([^\s,]+)$/i.exec(authorization)?.[1];
+  const apiKey = token && store.data.apiKeys.find(({ key }) => key === token);
+  if (!apiKey) throw new AppError("unauthorized");
+  return apiKey;
+}
+
+function authorize(role, method, pattern) {
+  if (role === "manager") return;
+  if ((role === "viewer" || role === "cook") && method === "GET" && pattern !== "/audit") return;
+  if (role === "cook" && method === "POST" && cookRoutes.has(pattern)) return;
+  throw new AppError("forbidden");
+}

